.theme-dark,
.theme-light {
    --git-delete-bg: #ff475040;
    --git-delete-hl: #96050a75;
    --git-insert-bg: #68d36840;
    --git-insert-hl: #23c02350;
    --git-change-bg: #ffd55840;
    --git-selected: #3572b0;

    --git-delete: #cc3333;
    --git-insert: #399839;
    --git-change: #d0b44c;
    --git-move: #3572b0;

    --git-conflict-ours: var(--color-cyan);
    --git-conflict-theirs: var(--color-blue);
    --git-conflict-ours-bg: color-mix(
        in oklch,
        var(--git-conflict-ours) 10%,
        transparent
    );
    --git-conflict-theirs-bg: color-mix(
        in oklch,
        var(--git-conflict-theirs) 10%,
        transparent
    );
    --git-conflict-ours-header-bg: color-mix(
        in oklch,
        var(--git-conflict-ours) 25%,
        transparent
    );
    --git-conflict-theirs-header-bg: color-mix(
        in oklch,
        var(--git-conflict-theirs) 25%,
        transparent
    );
    --git-conflict-ours-button-bg: color-mix(
        in oklab,
        var(--git-conflict-ours) 25%,
        var(--interactive-normal)
    );
    --git-conflict-theirs-button-bg: color-mix(
        in oklab,
        var(--git-conflict-theirs) 25%,
        var(--interactive-normal)
    );
    --git-conflict-base-button-bg: color-mix(
        in oklab,
        var(--color-purple) 15%,
        var(--interactive-normal)
    );
    --git-conflict-base-bg: color-mix(
        in oklch,
        var(--color-purple) 4%,
        transparent
    );
}

