/* modules/music-player/src/components/player/AlbumDisc.css */
/**
 * 专辑唱片组件样式文件
 * 
 * 包含专辑唱片组件的所有样式，包括：
 * - 唱片容器和布局样式
 * - 唱片旋转动画
 * - 唱针动画（播放/暂停时的移动）
 * - 切换动画（上一首/下一首时的滑动效果）
 * - 唱片阴影效果
 * - 拖动进度功能样式
 * - 移动端适配样式
 */

/* ========== 容器样式 ========== */
.music-player .album-container-wrapper {
    position: relative;
    display: flex;
    align-items: flex-end;
    justify-content: center;
    overflow: hidden;
    min-height: 405px;
	max-height: 450px;
    min-width: 320px;
	margin-bottom: 32px;
}

.music-player .disc-shadow {
	position: absolute;
	width: 320px;
	height: 320px;
	border-radius: 50%;
	/* 浅色模式：黑色半透明 */
	background: rgba(0, 0, 0, 0.03);
	/* 只让内圈（290px）之外的圆环显示：用遮罩把中心挖掉，
	   遮罩会连同背景填充一起裁剪 */
	-webkit-mask-image: radial-gradient(circle closest-side, transparent 0 89%, #000 91%);
	mask-image: radial-gradient(circle closest-side, transparent 0 89%, #000 91%);
	bottom: 0;
	left: 50%;
	transform: translateX(-50%);
	z-index: 0;
	pointer-events: none;
}

/* 深色模式：白色半透明 */
.theme-dark .music-player .disc-shadow {
	background: rgba(255, 255, 255, 0.03);
}

.music-player .pan-container {
	position: relative;
	width: 300px;
	height: 300px;
	display: flex;
	align-items: flex-end;
	justify-content: center;
	z-index: 1;
}

.music-player .needle {
	position: absolute;
	top: -107px;
	left: 50%;
	transform-origin: 18px 10px;
	transform: translateX(-18px) rotate(-30deg);
	transition: transform 0.3s ease;
	z-index: 10;
	pointer-events: none;
}

.music-player .needle.playing {
	transform: translateX(-18px) rotate(0deg);
}

.music-player .needle-image {
	display: block;
	width: 100px;
	height: 167px;
	filter: drop-shadow(0 2px 4px rgba(0, 0, 0, 0.3));
	user-select: none;
	pointer-events: none;
	object-fit: contain;
	transform-origin: 18px 10px;
}

.music-player .needle-image.needle-image-embedded {
	object-fit: unset;
	background-size: contain;
	background-repeat: no-repeat;
	background-position: center;
}

.music-player .album-container {
	position: relative;
	width: 300px;
	height: 300px;
	margin: 0 auto;
	display: flex;
	align-items: center;
	justify-content: center;
	touch-action: pan-y;
}

.music-player .disc-background {
	position: absolute;
	width: 300px;
	height: 300px;
	border-radius: 50%;
	object-fit: contain;
	user-select: none;
	pointer-events: none;
	z-index: 0;
	opacity: 0.9;
}

/* 由构建注入 background-image（data URL），替代 <img src>，大图不进 main.js */
.music-player .disc-background.disc-background-embedded {
	object-fit: unset;
	background-size: contain;
	background-repeat: no-repeat;
	background-position: center;
}

.music-player .album-image {
	position: relative;
	width: 200px;
	height: 200px;
	border-radius: 50%;
	background-size: cover;
	background-position: center;
	background-color: var(--background-modifier-border);
	box-shadow:
		0 4px 16px rgba(0, 0, 0, 0.3),
		inset 0 0 0 2px rgba(0, 0, 0, 0.1);
	display: flex;
	align-items: center;
	justify-content: center;
	color: var(--text-muted);
	z-index: 1;
	overflow: hidden;
}

.music-player .album-image.playing {
	animation: rotate 20s linear infinite;
}

.music-player .album-image.dragging {
	animation-play-state: paused;
}

.music-player .shadow-disc {
	opacity: 0;
	pointer-events: none;
}

@keyframes rotate {
	from {
		transform: rotate(0deg);
	}
	to {
		transform: rotate(360deg);
	}
}

.music-player .album-placeholder {
	display: flex;
	align-items: center;
	justify-content: center;
	width: 100%;
	height: 100%;
	color: var(--text-muted);
	font-size: 32px;
}



/* modules/music-player/src/components/player/LyricsExtendedFull.css */
/**
 * 逐字时间歌词完整列表组件样式文件
 * 
 * 包含逐字时间歌词完整列表的所有样式，包括：
 * - 歌词列表容器和滚动样式
 * - 歌词行样式
 * - 当前播放行高亮样式
 * - 播放过的歌词行样式
 * - 逐字字符样式
 * - 卡拉OK 逐字高亮效果
 * - 空状态样式
 */

/* ========== 逐字歌词列表容器 ========== */
.music-player .lyrics-extended {
	width: 100%;
	height: 100%;
	display: flex;
	flex-direction: column;
	align-items: center;
	justify-content: flex-start;
}

.music-player .lyrics-extended-scroll {
	overflow-y: auto;
	overflow-x: hidden;
	scroll-behavior: smooth;
	width: 100%;
	height: 100%;
	/* 与普通歌词视图（LyricsFull.css）一致：隐藏滚动条 */
	scrollbar-width: none;
	-ms-overflow-style: none;
}

.music-player .lyrics-extended-scroll::-webkit-scrollbar {
	display: none;
	width: 0;
	height: 0;
}

.music-player .lyrics-extended-line {
	display: flex;
	align-items: center;
	justify-content: center;
	width: 100%;
	padding: 8px 0;
	text-align: center;
	transition: all 0.3s ease;
	opacity: 0.5;
}

.music-player .lyrics-extended-line.is-active .lyrics-extended-text {
	color: var(--interactive-accent);
}

.music-player .lyrics-extended-line.is-played .lyrics-extended-text {
	color: var(--interactive-accent);
}

.music-player .lyrics-extended-line.is-playing {
	opacity: 1;
}

.music-player .lyrics-extended-text {
	cursor: pointer;
	color: var(--text-normal);
	transition: color 0.2s ease;
	user-select: none;
	display: inline-block;
	white-space: pre-wrap;
	word-break: break-word;
	letter-spacing: 0.04em;
}

.music-player .lyrics-extended-line.is-playing .lyrics-extended-text {
	color: var(--interactive-accent);
	font-size: 1.15em;
	font-weight: 600;
}

.music-player .lyrics-extended-char {
	display: inline-block;
	position: relative;
	vertical-align: baseline;
	line-height: inherit;
	padding: 0 0.06em;
	box-sizing: content-box;
}

.music-player .lyrics-extended-char.is-ws {
	min-width: 0.35em;
}

/* 背景层 */
.music-player .lyrics-extended-char-bg {
	display: inline-block;
	position: relative;
	z-index: 0;
	color: var(--text-normal);
	opacity: 0.5;
	font-weight: 600;
}

/* 播放过的歌词和当前行的背景文字颜色 */
.music-player .lyrics-extended-line.is-played .lyrics-extended-char-bg,
.music-player .lyrics-extended-line.is-playing .lyrics-extended-char-bg {
	color: var(--interactive-accent);
	opacity: 0.45;
}

/* 从左向右揭示（裁剪宽度，避免 scaleX 拉伸） */
.music-player .lyrics-extended-char-fill-clip {
	position: absolute;
	left: 0;
	top: 0;
	bottom: 0;
	overflow: hidden;
	max-width: 100%;
	z-index: 1;
	pointer-events: none;
	will-change: width;
}

.music-player .lyrics-extended-char-fill {
	position: absolute;
	left: 0;
	top: 0;
	display: inline-block;
	white-space: nowrap;
	line-height: inherit;
	color: var(--interactive-accent);
	font-weight: 600;
}

.music-player .lyrics-extended-line.is-playing .lyrics-extended-char-bg,
.music-player .lyrics-extended-line.is-playing .lyrics-extended-char-fill {
	font-weight: 600;
}

.music-player .lyrics-extended-char.is-word-unit {
	letter-spacing: normal;
	padding: 0 0.1em;
}

.music-player .lyrics-extended-empty {
	width: 100%;
	height: 100%;
	display: flex;
	align-items: center;
	justify-content: center;
}

.music-player .lyrics-extended-empty-text {
	color: var(--text-faint);
	font-size: 0.9em;
}



/* modules/music-player/src/components/player/LyricsExtendedTriplet.css */
/**
 * 逐字时间歌词三行组件样式文件
 * 
 * 包含逐字时间歌词三行显示的所有样式，包括：
 * - 逐字歌词文本样式
 * - 逐字字符容器样式
 * - 背景文字（未填充部分）样式
 * - 填充文字（已填充部分）样式
 * - 当前行高亮样式
 * - 卡拉OK 逐字高亮效果
