}

.music-player .lyrics-extended-triplet-char.is-ws {
	min-width: 0.35em;
}

/* 背景层（未唱到部分） */
.music-player .lyrics-extended-triplet-char-bg {
	display: inline-block;
	position: relative;
	z-index: 0;
	color: var(--text-muted);
