}

/* 封面占位符中的图标 */
.music-player .playlist-item-placeholder svg {
	width: 24px;
	height: 24px;
}

/* 文本信息容器（标题和元数据） */
.music-player .playlist-item-text {
	flex: 1;
	min-width: 0;
	display: flex;
	flex-direction: column;
	gap: 4px;
}

/* 曲目标题样式 */
.music-player .playlist-item-title {
	font-size: 14px;
	font-weight: 500;
	color: var(--text-normal);
	line-height: 1.4;
	overflow: hidden;
	text-overflow: ellipsis;
	white-space: nowrap;
	display: flex;
	align-items: center;
}

/* 激活状态下的标题样式 */
.music-player .playlist-item.is-active .playlist-item-title {
	color: var(--interactive-accent);
	font-weight: 600;
}

/* 元数据样式（艺术家、专辑等信息） */
.music-player .playlist-item-meta {
	font-size: 12px;
	line-height: 1.4;
	overflow: hidden;
	text-overflow: ellipsis;
	white-space: nowrap;
}

.music-player .playlist-item.is-active .playlist-item-meta {
	color: var(--interactive-accent);
}

/* 悬停效果 */
.music-player .playlist-item:hover:not(.is-active) {
	background: var(--background-modifier-hover);
}



/* vinyl assets: inlined from modules/music-player/src/assets at merge time */
.music-player .disc-background.disc-background-embedded{background-image:url("data:image/png;base64,")}
.music-player .needle-image.needle-image-embedded{background-image:url("data:image/png;base64,")}


