    margin-top: 8px !important; /* Visual offset from the search bar */
    margin-left: -30px !important;  /* Offset to account for the search icon */
    border: 1px solid var(--background-modifier-border) !important;
    border-radius: 4px !important;
    box-shadow: var(--shadow-s) !important;
}

/* Suggestion Item */
.abstract-folder-suggestion-item {
    display: flex;
    flex-direction: column;
    padding: 6px 10px;
}

.abstract-folder-suggestion-item .suggestion-content {
    font-size: var(--font-ui-medium);
    color: var(--text-normal);
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

.abstract-folder-suggestion-item .suggestion-aux {
    display: flex;
    align-items: center;
    gap: 4px;
    margin-top: 2px;
    font-size: var(--font-ui-smaller);
    color: var(--text-muted);
