  padding: 1px 5px;
}

.kanban-trigger-arrow {
  font-size: 10px;
}

.kanban-dropdown-menu {
  min-width: 150px;
}

.kanban-dropdown-item {
  padding: 6px 10px;
  font-size: 12px;
}

/* Task tracker header вЂ” compact on mobile */
.task-tracker-header {
  padding: 6px 8px;
  gap: 6px;
}

.task-tracker-title {
  font-size: 11px;
}

.task-tracker-date {
  font-size: 10px;
  max-width: 80px;
}

.task-tracker-count {
  font-size: 10px;
  padding: 2px 6px;
}

.task-tracker-btn {
  min-width: 28px;
  min-height: 28px;
  font-size: 13px;
  padding: 3px 6px;
}

/* Mobile header */
.task-tracker-mob-header {
  display: flex;
  align-items: center;
  gap: 5px;
  padding: 8px 10px 6px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.05);
  /* Sticky chrome must be opaque — a translucent gradient let the list
     show through when scrolling under the bar. No backdrop-filter (WebKit). */
  background: var(--background-primary, #1a1a2e);
  position: sticky;
  top: 0;
  z-index: 20;
  /* Chrome rows must keep full height — never let flex shrink clip them
     (overflow-x on filters turns overflow-y into auto and would cut chips). */
  flex-shrink: 0;
  /* Keep hit-testing reliable on touch WebKit: no backdrop-filter here
     (it can drop taps on sticky bars) and force pointer events on. */
  pointer-events: auto;
  touch-action: manipulation;
}

.task-tracker-mob-header .task-tracker-btn {
  min-width: 34px;
  min-height: 34px;
  border-radius: 10px;
  font-size: 14px;
  padding: 0;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border: 1px solid rgba(255, 255, 255, 0.05);
  background: rgba(255, 255, 255, 0.03);
}

.task-tracker-mob-header .task-tracker-btn:active {
  transform: scale(0.94);
}

.task-tracker-mob-header .add-btn {
  min-width: 36px;
  min-height: 36px;
  border-radius: 11px;
  font-size: 20px;
  font-weight: 500;
  line-height: 1;
  background: var(--mcp-accent, #7c5cfc);
  color: #fff;
  border: none;
  box-shadow: none;
}

.task-tracker-mob-header .add-btn:hover {
  filter: brightness(1.06);
  color: #fff;
}

.task-tracker-mob-date {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 4px 12px 8px;
  font-size: 13px;
  font-weight: 600;
  letter-spacing: 0;
  color: var(--mcp-text);
  background: var(--background-primary, #1a1a2e);
  /* Below filters in paint order — filters chips stay visible if boxes meet. */
  position: relative;
  z-index: 1;
  flex-shrink: 0;
}

.task-tracker-mob-date .task-tracker-date,
.task-tracker-mob-date .task-tracker-date-all {
  padding: 4px 12px;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.04);
  border: 1px solid rgba(255, 255, 255, 0.05);
  box-shadow: none;
}

.task-tracker-mob-date .date-nav-btn {
  width: 30px;
  height: 30px;
  min-height: 30px;
  border-radius: 10px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 16px;
  line-height: 1;
  background: rgba(255, 255, 255, 0.04);
  border: 1px solid rgba(255, 255, 255, 0.06);
  color: var(--mcp-text-muted);
  transition: background 0.15s, transform 0.12s;
}

.task-tracker-mob-date .date-nav-btn:active {
  transform: scale(0.92);
  background: rgba(255, 255, 255, 0.08);
}

/* Mobile filter tabs
   NOTE: do NOT put mask-image on this element — on iOS/Android WebKit
   masked scrollers stop delivering touch hits to child buttons. */
.task-tracker-mob-filters {
  display: flex;
  gap: 5px;
  padding: 2px 10px 6px;
  overflow-x: auto;
  -webkit-overflow-scrolling: touch;
  scrollbar-width: none;
  position: relative;
  /* Status chips must paint above the date row, never under it. */
  z-index: 2;
  flex-shrink: 0;
  background: var(--background-primary, #1a1a2e);
  touch-action: pan-x;
}

.task-tracker-mob-filters::after {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  background: linear-gradient(90deg, transparent, #000 6px, #000 calc(100% - 6px), transparent);
  opacity: 0;
}

.task-tracker-mob-filters::-webkit-scrollbar {
  display: none;
}

.mob-filter-btn {
  flex-shrink: 0;
  padding: 5px 11px;
  font-size: 11.5px;
  font-weight: 550;
  letter-spacing: 0;
  color: var(--mcp-text-muted);
  background: rgba(255, 255, 255, 0.03);
  border: 1px solid rgba(255, 255, 255, 0.05);
  border-radius: 999px;
  cursor: pointer;
  touch-action: manipulation;
  -webkit-tap-highlight-color: transparent;
  transition:
    background 0.15s ease,
    color 0.15s ease,
    border-color 0.15s ease;
  white-space: nowrap;
  min-height: 30px;
}

.mob-filter-btn:active {
  transform: scale(0.96);
}

.mob-filter-btn.active {
  background: color-mix(in srgb, var(--mcp-accent, #7c5cfc) 18%, transparent);
  color: var(--text-accent, var(--mcp-accent));
  border-color: color-mix(in srgb, var(--mcp-accent, #7c5cfc) 35%, transparent);
  box-shadow: none;
}

.mob-filter-btn:hover:not(.active) {
  background: rgba(255, 255, 255, 0.08);
  color: var(--mcp-text);
}

/* Mobile project picker */
.task-tracker-mob-project-picker {
  position: relative;
  flex: 1;
  min-width: 0;
}

.task-tracker-mob-project-btn {
  display: flex;
  align-items: center;
  gap: 8px;
  width: 100%;
  padding: 8px 12px;
  font-size: 13px;
