  border-radius: 12px;
  cursor: pointer;
  white-space: nowrap;
  overflow: hidden;
  min-height: 36px;
  transition: background 0.15s, border-color 0.15s;
}

.task-tracker-mob-project-btn:active {
  transform: scale(0.98);
  background: rgba(255, 255, 255, 0.07);
}

.project-picker-arrow {
  font-size: 10px;
  margin-left: auto;
  flex-shrink: 0;
  opacity: 0.7;
  transition: transform 0.2s;
}

.project-picker-arrow.rotated {
  transform: rotate(180deg);
}

.task-tracker-mob-project-dropdown {
  position: absolute;
  top: 100%;
  left: 0;
  right: 0;
  margin-top: 6px;
  background: var(--mcp-surface-2, rgba(30, 32, 48, 0.96));
  border: 1px solid var(--mcp-glass-border, rgba(255, 255, 255, 0.1));
  border-radius: 14px;
  box-shadow:
    0 16px 40px rgba(0, 0, 0, 0.35),
    0 0 0 1px rgba(255, 255, 255, 0.04) inset;
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
  z-index: 100;
  min-width: 180px;
  max-height: 280px;
  overflow-y: auto;
  padding: 6px;
  animation: sch-popover-in 0.18s cubic-bezier(0.2, 0.8, 0.2, 1);
}

.project-dropdown-item {
  display: flex;
  align-items: center;
  gap: 8px;
  width: 100%;
  padding: 10px 12px;
  font-size: 13px;
  color: var(--mcp-text-muted);
