/* Loading effect while AI writes the description (no button spin) */
.qa2-desc-box.is-ai-loading .qa2-desc-input {
  border-color: color-mix(in srgb, var(--interactive-accent, #7c5cfc) 55%, transparent);
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--interactive-accent, #7c5cfc) 18%, transparent);
  background:
    linear-gradient(
      100deg,
      transparent 20%,
      color-mix(in srgb, var(--interactive-accent, #7c5cfc) 14%, transparent) 40%,
      color-mix(in srgb, var(--interactive-accent, #7c5cfc) 22%, transparent) 50%,
      color-mix(in srgb, var(--interactive-accent, #7c5cfc) 14%, transparent) 60%,
      transparent 80%
    ),
    rgba(255, 255, 255, 0.04);
  background-size: 200% 100%;
  animation: qa2-desc-shimmer 1.4s ease-in-out infinite;
}

.qa2-desc-box.is-ai-loading::after {
  content: "";
  position: absolute;
  left: 12px;
  right: 12px;
  bottom: 8px;
  height: 2px;
  border-radius: 2px;
  background: color-mix(in srgb, var(--interactive-accent, #7c5cfc) 22%, transparent);
  overflow: hidden;
  pointer-events: none;
}

.qa2-desc-box.is-ai-loading::before {
  content: "";
  position: absolute;
  left: 12px;
  bottom: 8px;
  height: 2px;
  width: 36%;
  border-radius: 2px;
  background: var(--interactive-accent, #7c5cfc);
  animation: qa2-desc-progress 1.15s ease-in-out infinite;
  z-index: 1;
  pointer-events: none;
}

@keyframes qa2-desc-shimmer {
