/* РІвЂўС’РІвЂўС’РІвЂўС’ VIEW SWITCH MOTION РІвЂўС’РІвЂўС’РІвЂўС’РІвЂўС’РІвЂўС’РІвЂўС’РІвЂўС’РІвЂўС’РІвЂўС’РІвЂўС’РІвЂўС’РІвЂўС’РІвЂўС’РІвЂўС’РІвЂўС’РІвЂўС’РІвЂўС’РІвЂўС’ */
/* Р СџР В»Р В°Р Р†Р Р…Р С•: РЎвЂљР С•Р В»РЎРЉР С”Р С• opacity + Р В»РЎвЂР С–Р С”Р С‘Р в„– Y, Р В±Р ВµР В· scale.
   Header Р С—Р С•РЎвЂЎРЎвЂљР С‘ Р Р…Р Вµ Р Т‘Р Р†Р С‘Р С–Р В°Р ВµРЎвЂљРЎРѓРЎРЏ вЂ” Р С—Р ВµРЎР‚Р ВµР С”Р В»РЎР‹РЎвЂЎР В°РЎвЂљР ВµР В»РЎРЉ Р С•РЎвЂ°РЎС“РЎвЂ°Р В°Р ВµРЎвЂљРЎРѓРЎРЏ РЎРѓРЎвЂљР В°Р В±Р С‘Р В»РЎРЉР Р…РЎвЂ№Р С. */
.view-switch-leave {
  animation: view-switch-leave 0.18s cubic-bezier(0.4, 0, 0.6, 1) forwards;
  pointer-events: none;
}

/* Header must stay operable during leave — it is the tab switcher. */
.view-switch-leave > .view-switch-header {
  animation: none;
  opacity: 1;
  pointer-events: auto;
}

.view-switch-enter > :not(.view-switch-header),
.task-view.view-switch-enter > :not(.view-switch-header),
.schedule-view-container.view-switch-enter > :not(.view-switch-header),
.kanban-view-container.view-switch-enter > :not(.view-switch-header),
.mobile-tasks.view-switch-enter > :not(.view-switch-header) {
  animation: view-switch-enter 0.32s cubic-bezier(0.22, 1, 0.36, 1);
}

.view-switch-enter > .view-switch-header,
.task-view.view-switch-enter > .view-switch-header,
.schedule-view-container.view-switch-enter > .view-switch-header,
.kanban-view-container.view-switch-enter > .view-switch-header {
  animation: view-switch-fade-in 0.2s ease;
}

@keyframes view-switch-leave {
  from {
    opacity: 1;
    transform: translateY(0);
  }
  to {
    opacity: 0;
    transform: translateY(3px);
  }
}

@keyframes view-switch-enter {
  from {
    opacity: 0;
    transform: translateY(6px);
  }
  to {
    opacity: 1;
    transform: none;
  }
}

@keyframes view-switch-fade-in {
  from {
    opacity: 0.4;
  }
  to {
    opacity: 1;
  }
}

@media (prefers-reduced-motion: reduce) {
  .view-switch-leave,
  .view-switch-leave > .view-switch-header,
  .view-switch-enter > :not(.view-switch-header),
  .task-view.view-switch-enter > :not(.view-switch-header),
  .schedule-view-container.view-switch-enter > :not(.view-switch-header),
  .kanban-view-container.view-switch-enter > :not(.view-switch-header),
  .mobile-tasks.view-switch-enter > :not(.view-switch-header),
  .view-switch-enter > .view-switch-header,
  .task-view.view-switch-enter > .view-switch-header,
  .schedule-view-container.view-switch-enter > .view-switch-header,
  .kanban-view-container.view-switch-enter > .view-switch-header {
    animation: none;
  }

  .view-switch-btn {
    transition: none;
  }
}

