    align-items: flex-start;
    gap: 8px;
    flex-wrap: wrap;
  }

  .kbm-head .kbm-add-col-btn {
    width: 100%;
    order: 2;
  }

  /* iOS zoom prevention */
  .kbm-input,
  .kbm-col-icon,
  .kbm-col-title {
    font-size: 16px;
    min-height: 44px;
  }

  .kbm-icon-grid {
    gap: 8px;
  }

  .kbm-icon-btn {
    width: 44px;
    height: 44px;
    font-size: 20px;
    /* 6 across on a ~360px phone */
    flex: 1 1 calc(16.66% - 8px);
    max-width: calc(20% - 8px);
  }

  .kbm-section-head .kbm-add-col-btn {
    width: 100%;
    min-height: 44px;
  }

  .kbm-section-head {
    flex-direction: column;
    align-items: stretch;
    gap: 8px;
  }

  .kbm-col-top {
    gap: 8px;
  }

  .kbm-col-icon {
    width: 44px;
    min-width: 44px;
  }

  .kbm-col-color {
    width: 44px;
    height: 44px;
  }

  .kbm-col-del,
  .kbm-move-btn {
    width: 44px;
    height: 40px;
    min-height: 40px;
  }

  .kbm-status-chip {
    min-height: 38px;
    padding: 8px 12px;
    font-size: 12px;
  }

  .kbm-col-list,
  .kbm-board-list {
    max-height: none;
    overflow-y: visible;
    padding-right: 0;
  }

  /* Content becomes the scroller so the sticky footer stays put */
  .wf-dialog-container.kbm-board-modal .wf-dialog-content,
  .wf-dialog-container.kbm-board-modal .wf-dialog-content {
