@media (max-width: 768px) {
  .kanban-board {
    padding: 8px;
    gap: 8px;
    overflow-x: auto;
    overflow-y: hidden;
    scroll-snap-type: x proximity;
    -webkit-overflow-scrolling: touch;
    overscroll-behavior-x: contain;
  }

  .kanban-column {
    min-width: min(260px, 78vw);
    max-width: min(300px, 85vw);
    flex: 0 0 auto;
    scroll-snap-align: start;
    scroll-margin-left: 8px;
  }

  .kanban-filters {
    overflow: visible;
    flex-wrap: wrap;
    padding: 8px 8px 0;
    gap: 6px;
  }

  .kanban-filters::-webkit-scrollbar {
    display: none;
  }

  .kanban-filter-btn {
    flex-shrink: 0;
    min-height: 36px;
    padding: 7px 12px;
    font-size: 12px;
  }

  .kanban-column-header {
    padding: 10px 12px;
    gap: 6px;
  }

  .kanban-card {
    padding: 10px;
    margin: 8px;
  }

  /* Compact icon button — not a full-width bar */
  .kanban-col-add {
    width: 32px;
    height: 32px;
    min-height: 32px;
    min-width: 32px;
    margin: 0;
    flex-shrink: 0;
    font-size: 18px;
    border-radius: 8px;
  }

  /* Fixed so the menu is not clipped by .kanban-filters / view overflow */
  .kanban-project-dropdown.is-fixed {
    position: fixed;
    z-index: 400;
    max-width: min(280px, calc(100vw - 16px));
    max-height: min(50vh, 320px);
  }
}

@media (max-width: 480px) {
  .kanban-board {
    padding: 6px;
    gap: 6px;
  }

  .kanban-column {
    min-width: calc(100vw - 28px);
    max-width: calc(100vw - 28px);
  }

  .kanban-filters {
    padding: 6px 6px 0;
    gap: 6px;
    overflow: visible;
    flex-wrap: wrap;
  }

  .kanban-project-dropdown {
    left: 8px;
    right: 8px;
    max-width: calc(100vw - 16px);
  }

  .kanban-project-dropdown.is-fixed {
    left: 8px;
    right: 8px;
    max-width: calc(100vw - 16px);
    width: auto;
  }

  .kanban-card-actions {
    opacity: 1;
    gap: 6px;
  }

  .kanban-card-btn {
    width: 32px;
    height: 32px;
    min-width: 32px;
    min-height: 32px;
    font-size: 13px;
  }

  .kanban-trigger-label {
    max-width: 110px;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
  }
}

/* Touch devices: always show card actions (no hover) */
@media (hover: none) and (pointer: coarse) {
  .kanban-card-actions {
    opacity: 1;
  }

  .kanban-card-btn {
    width: 32px;
    height: 32px;
    min-height: 32px;
  }
}

/* ===== AI Extract Modal вЂ” fully standalone, no tm-* dependency ===== */

