/* в”Ђв”Ђ AI Summary: scan effect (same language as AI extract) в”Ђв”Ђ */
.ai-summary-scan {
  position: relative;
  border: 1px solid rgba(95, 153, 225, 0.28);
  border-radius: 12px;
  background: rgba(95, 153, 225, 0.06);
  overflow: hidden;
  transition: border-color 0.25s ease, box-shadow 0.25s ease;
}

.ai-summary-modal.scanning .ai-summary-scan {
  border-color: rgba(95, 153, 225, 0.5);
  box-shadow:
    0 0 0 2px rgba(95, 153, 225, 0.2),
    0 0 28px rgba(95, 153, 225, 0.22);
  animation: ai-pulse-glow 1.25s ease-in-out infinite;
}

/* Horizontal scan line sweeping the output */
.ai-summary-modal.scanning .ai-summary-scan::before {
  content: "";
  position: absolute;
  left: 0;
  right: 0;
  top: 0;
  height: 2px;
  z-index: 3;
  background: linear-gradient(90deg, transparent, #5f99e1 30%, #8ec0ff 50%, #5f99e1 70%, transparent);
  box-shadow: 0 0 12px rgba(95, 153, 225, 0.65);
  animation: ai-summary-scan-line 1.35s ease-in-out infinite;
  pointer-events: none;
}

/* Soft beam following the line */
.ai-summary-modal.scanning .ai-summary-scan::after {
  content: "";
  position: absolute;
  left: 0;
  right: 0;
  top: 0;
  height: 28%;
  z-index: 2;
  background: linear-gradient(
    180deg,
    rgba(95, 153, 225, 0.16),
    rgba(95, 153, 225, 0.04) 55%,
    transparent
  );
  animation: ai-summary-scan-line 1.35s ease-in-out infinite;
  pointer-events: none;
}

@keyframes ai-summary-scan-line {
  0% { transform: translateY(-10%); opacity: 0; }
  12% { opacity: 1; }
  88% { opacity: 1; }
  100% { transform: translateY(340%); opacity: 0; }
}

.ai-summary-modal.scanning .ai-summary-textarea {
  border-color: transparent;
  background: rgba(8, 16, 28, 0.35);
  color: #dce7f2;
  caret-color: #5f99e1;
}

.ai-summary-modal.scanning .ai-summary-textarea::selection {
  background: rgba(95, 153, 225, 0.28);
}

.ai-summary-modal.generating .ai-summary-scan {
  border-color: rgba(95, 153, 225, 0.4);
}

.ai-summary-modal.generating .ai-summary-textarea {
  border-color: transparent;
  box-shadow: none;
}

/* Status caret during stream */
.ai-summary-modal.scanning .ai-summary-status.busy::after {
  content: "\258C";
  margin-left: 2px;
  color: #5f99e1;
  animation: ai-caret 0.9s steps(1) infinite;
}

@media (prefers-reduced-motion: reduce) {
  .ai-summary-modal.scanning .ai-summary-scan::before,
  .ai-summary-modal.scanning .ai-summary-scan::after,
  .ai-summary-modal.scanning .ai-summary-status.busy::after {
    animation: none;
  }
  .ai-summary-modal.scanning .ai-summary-scan::before {
    display: none;
  }
}

