.workout-plan-modal .workout-status-ok { color: var(--mcp-success); }
.workout-plan-modal .workout-status.is-busy .workout-status-busy::before {
  content: "";
  display: inline-block;
  width: 10px;
  height: 10px;
  margin-right: 6px;
  border-radius: 50%;
  border: 2px solid var(--mcp-amber);
  border-top-color: transparent;
  vertical-align: -1px;
  animation: wo-spin 0.7s linear infinite;
}
@keyframes wo-spin {
  to { transform: rotate(360deg); }
}
.workout-plan-modal .wo-gen-anim {
  position: relative;
  height: 88px;
  border-radius: 12px;
  overflow: hidden;
  background: var(--background-secondary, var(--mcp-surface-2));
  border: 1px solid var(--background-modifier-border, rgba(255, 255, 255, 0.06));
}
.workout-plan-modal .wo-gen-anim::before {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(
    90deg,
    transparent 0%,
    var(--mcp-accent-dim) 45%,
    var(--mcp-accent-glow) 55%,
    transparent 100%
  );
  transform: translateX(-100%);
  animation: wo-shimmer 1.2s ease-in-out infinite;
}
.workout-plan-modal .wo-gen-anim::after {
  content: "AI";
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.85rem;
  font-weight: 700;
  letter-spacing: 0.2em;
  color: var(--mcp-accent);
  opacity: 0.85;
  animation: wo-pulse 1.2s ease-in-out infinite;
}
@keyframes wo-shimmer {
