.hearth-instant-day-name {
	color: var(--text-muted);
}

.hearth-instant-day-icon {
	display: flex;
	color: var(--text-muted);
}

.hearth-instant-day-icon svg {
	width: 16px;
	height: 16px;
}

.hearth-instant-day-temp {
	color: var(--text-normal);
	white-space: nowrap;
