.hearth-instant-alt {
	padding-top: 5px;
	padding-bottom: 5px;
}

.hearth-instant-alt .hearth-result-name {
	font-size: 0.85rem;
}

/* The "the bar can answer questions" hint and the "?" row (search.ts). */
.hearth-result.hearth-tips-hint .hearth-result-icon {
	color: var(--interactive-accent);
}

.hearth-result.hearth-tips-hint .hearth-result-text {
