/* ---- Search tips dialog (searchtips.ts) ---- */
.hearth-tips-heading {
	margin: 16px 0 6px;
	font-size: var(--font-ui-medium);
}

.hearth-tips-list {
	display: flex;
	flex-direction: column;
	gap: 10px;
}

.hearth-tips-row {
	display: flex;
	align-items: flex-start;
	gap: 12px;
}

.hearth-tips-row.is-off {
	opacity: 0.55;
}

.hearth-tips-icon {
	display: flex;
	flex-shrink: 0;
	margin-top: 2px;
	color: var(--text-muted);
}

.hearth-tips-text {
	flex: 1;
	min-width: 0;
}

.hearth-tips-title {
	display: flex;
	align-items: center;
	gap: 8px;
	color: var(--text-normal);
	font-weight: 600;
}

.hearth-tips-off {
	padding: 0 6px;
	border-radius: var(--radius-s);
	background: var(--background-modifier-hover);
	color: var(--text-muted);
	font-size: 0.72rem;
