:is(.hearth-card.is-expressive, .hearth-x-modal, .hearth-search-wrap.is-expressive) .hearth-list > .hearth-list-item:first-child,
:is(.hearth-card.is-expressive, .hearth-x-modal, .hearth-search-wrap.is-expressive) .hearth-list > .hearth-bookmark-group:first-child > .hearth-bookmark-group-header {
	border-top-left-radius: 20px;
	border-top-right-radius: 20px;
}

:is(.hearth-card.is-expressive, .hearth-x-modal, .hearth-search-wrap.is-expressive) .hearth-list > .hearth-list-item:last-child,
:is(.hearth-card.is-expressive, .hearth-x-modal, .hearth-search-wrap.is-expressive) .hearth-list > .hearth-list-item.is-last-unclipped {
	border-bottom-left-radius: 20px;
	border-bottom-right-radius: 20px;
}

:is(.hearth-card.is-expressive, .hearth-x-modal, .hearth-search-wrap.is-expressive) .hearth-list-item:hover {
	background: var(--x-surface-highest);
	border-radius: 20px;
}

:is(.hearth-card.is-expressive, .hearth-x-modal, .hearth-search-wrap.is-expressive) .hearth-list-icon {
	align-items: center;
	justify-content: center;
	width: 28px;
	height: 28px;
	border-radius: 999px;
	background: var(--x-container);
	color: var(--x-on-container);
}

:is(.hearth-card.is-expressive, .hearth-x-modal, .hearth-search-wrap.is-expressive) .hearth-list-icon .svg-icon {
	width: 16px;
	height: 16px;
	stroke-width: 2.1px;
}

:is(.hearth-card.is-expressive, .hearth-x-modal, .hearth-search-wrap.is-expressive) .hearth-list-label {
	font-weight: 500;
}

/* A leading badge sits closer to the row's edge than text does: a row without
 * one (a task's check, a URL bookmark without its favicon) keeps the full
 * inset, and the badge pulls itself out into it. */
:is(.hearth-card.is-expressive, .hearth-x-modal, .hearth-search-wrap.is-expressive) .hearth-list-item > .hearth-list-icon:first-child {
	margin-left: -7px;
}

:is(.hearth-card.is-expressive, .hearth-x-modal, .hearth-search-wrap.is-expressive) .hearth-list-item > .hearth-bookmark-chevron:first-child {
	margin-left: -5px;
}

:is(.hearth-card.is-expressive, .hearth-x-modal, .hearth-search-wrap.is-expressive) .hearth-list-item.has-excerpt .hearth-list-icon {
	margin-top: 0;
}

/* Bookmark groups: the header a row like the others, its chevron on the badge's
 * side of it; nested rows step in. */
:is(.hearth-card.is-expressive, .hearth-x-modal, .hearth-search-wrap.is-expressive) .hearth-bookmark-group,
:is(.hearth-card.is-expressive, .hearth-x-modal, .hearth-search-wrap.is-expressive) .hearth-bookmark-group-children {
	gap: 3px;
}

:is(.hearth-card.is-expressive, .hearth-x-modal, .hearth-search-wrap.is-expressive) .hearth-bookmark-group-header {
	gap: 6px;
}

:is(.hearth-card.is-expressive, .hearth-x-modal, .hearth-search-wrap.is-expressive) .hearth-bookmark-group-header .hearth-list-label {
	font-weight: 700;
}

:is(.hearth-card.is-expressive, .hearth-x-modal, .hearth-search-wrap.is-expressive) .hearth-bookmark-chevron {
	width: 18px;
	margin-left: 2px;
	background: none;
	color: var(--x-on-container);
}

/* ---- Tiles: links, templater, favourites ------------------------------ */
:is(.hearth-card.is-expressive, .hearth-x-modal, .hearth-search-wrap.is-expressive) .hearth-link-tile,
:is(.hearth-card.is-expressive, .hearth-x-modal, .hearth-search-wrap.is-expressive) .hearth-fav-card {
