}

:is(.hearth-card.is-expressive, .hearth-x-modal, .hearth-search-wrap.is-expressive) .hearth-links.is-tile-scaled .hearth-link-tile {
	border-radius: clamp(12px, calc(var(--hearth-tile-cell) * 0.28), 32px);
}

/* Pressed-in on hover, the way an Expressive button morphs its corners. */
:is(.hearth-card.is-expressive, .hearth-x-modal, .hearth-search-wrap.is-expressive) .hearth-link-tile:hover,
:is(.hearth-card.is-expressive, .hearth-x-modal, .hearth-search-wrap.is-expressive) .hearth-fav-card:hover {
	background: var(--x-container);
	border-radius: 14px;
}

:is(.hearth-card.is-expressive, .hearth-x-modal, .hearth-search-wrap.is-expressive) .hearth-link-icon,
:is(.hearth-card.is-expressive, .hearth-x-modal, .hearth-search-wrap.is-expressive) .hearth-fav-icon {
	color: var(--x-on-container);
}

:is(.hearth-card.is-expressive, .hearth-x-modal, .hearth-search-wrap.is-expressive) .hearth-link-icon .svg-icon {
	stroke-width: 2.1px;
}

:is(.hearth-card.is-expressive, .hearth-x-modal, .hearth-search-wrap.is-expressive) .hearth-link-label,
:is(.hearth-card.is-expressive, .hearth-x-modal, .hearth-search-wrap.is-expressive) .hearth-fav-name {
	font-weight: 600;
}

:is(.hearth-card.is-expressive, .hearth-x-modal, .hearth-search-wrap.is-expressive) .hearth-link-tile.hearth-tile-has-image .hearth-link-label {
	border-radius: 999px;
}

:is(.hearth-card.is-expressive, .hearth-x-modal, .hearth-search-wrap.is-expressive) .hearth-favorites {
