/* ---- Clock ---------------------------------------------------------- */
:is(.hearth-card.is-expressive, .hearth-x-modal, .hearth-search-wrap.is-expressive) .hearth-clock {
	gap: 6px;
}

:is(.hearth-card.is-expressive, .hearth-x-modal, .hearth-search-wrap.is-expressive) .hearth-clock-time {
	font-size: clamp(2.2rem, 7.5vw, 3.4rem);
	font-weight: 800;
	letter-spacing: -0.05em;
	line-height: 1;
	font-variant-numeric: tabular-nums;
}

:is(.hearth-card.is-expressive, .hearth-x-modal, .hearth-search-wrap.is-expressive) .hearth-clock-greeting {
	padding: 3px 12px;
	border-radius: 999px;
	background: var(--x-container);
	color: var(--x-on-container);
	font-weight: 650;
}

:is(.hearth-card.is-expressive, .hearth-x-modal, .hearth-search-wrap.is-expressive) .hearth-clock-date {
	font-weight: 600;
}

/* The analogue face on a twelve-lobed cookie, hands as thick round strokes. */
:is(.hearth-card.is-expressive, .hearth-x-modal, .hearth-search-wrap.is-expressive) .hearth-analog {
	background: var(--x-surface-high);
	-webkit-mask: var(--x-clock-cookie) center / contain no-repeat;
	mask: var(--x-clock-cookie) center / contain no-repeat;
}

:is(.hearth-card.is-expressive, .hearth-x-modal, .hearth-search-wrap.is-expressive) .hearth-analog-face,
:is(.hearth-card.is-expressive, .hearth-x-modal, .hearth-search-wrap.is-expressive) .hearth-analog-tick {
	display: none;
}

:is(.hearth-card.is-expressive, .hearth-x-modal, .hearth-search-wrap.is-expressive) .hearth-analog-tick-major {
	stroke: var(--x-on-container);
	stroke-width: 3.2;
	stroke-linecap: round;
	opacity: 0.45;
}

:is(.hearth-card.is-expressive, .hearth-x-modal, .hearth-search-wrap.is-expressive) .hearth-analog-hour {
	stroke: var(--x-on-container);
	stroke-width: 7;
}

:is(.hearth-card.is-expressive, .hearth-x-modal, .hearth-search-wrap.is-expressive) .hearth-analog-min {
	stroke: var(--x-primary);
	stroke-width: 4.6;
}

:is(.hearth-card.is-expressive, .hearth-x-modal, .hearth-search-wrap.is-expressive) .hearth-analog-sec {
	stroke-width: 1.8;
}

:is(.hearth-card.is-expressive, .hearth-x-modal, .hearth-search-wrap.is-expressive) .hearth-analog-pin {
	fill: var(--x-primary);
	r: 4.5px;
}

/* The newer faces add a second tone: the accent turned a sixth of the way
 * round the colour wheel, Material's tertiary. */
:is(.hearth-card.is-expressive, .hearth-x-modal, .hearth-search-wrap.is-expressive) .hearth-clock {
	--x-tertiary: hsl(calc(var(--accent-h) + 60), calc(var(--accent-s) * 0.8), var(--accent-l));
	--x-tertiary-container: color-mix(in srgb, var(--x-tertiary) 24%, var(--background-primary));
	--x-on-tertiary-container: color-mix(in srgb, var(--x-tertiary) 55%, var(--text-normal));
}

/* Stacked: each half of the time on a tonal block of its own. */
:is(.hearth-card.is-expressive, .hearth-x-modal, .hearth-search-wrap.is-expressive) .hearth-clock-stacked {
	row-gap: 4px;
	--stack-size: clamp(1.6rem, min(26cqw, calc(var(--clock-room) * 0.4)), 6.4rem);
}

:is(.hearth-card.is-expressive, .hearth-x-modal, .hearth-search-wrap.is-expressive) .hearth-clock-stack-h,
:is(.hearth-card.is-expressive, .hearth-x-modal, .hearth-search-wrap.is-expressive) .hearth-clock-stack-m {
	padding: 0.06em 0.2em;
	border-radius: calc(var(--stack-size) * 0.34);
	font-weight: 800;
	letter-spacing: -0.06em;
	line-height: 1;
}

:is(.hearth-card.is-expressive, .hearth-x-modal, .hearth-search-wrap.is-expressive) .hearth-clock-stack-h {
	background: var(--x-container);
	color: var(--x-on-container);
	border-bottom-left-radius: calc(var(--stack-size) * 0.12);
	border-bottom-right-radius: calc(var(--stack-size) * 0.12);
}

:is(.hearth-card.is-expressive, .hearth-x-modal, .hearth-search-wrap.is-expressive) .hearth-clock-stack-m {
	background: var(--x-tertiary-container);
	color: var(--x-on-tertiary-container);
	border-top-left-radius: calc(var(--stack-size) * 0.12);
	border-top-right-radius: calc(var(--stack-size) * 0.12);
}

:is(.hearth-card.is-expressive, .hearth-x-modal, .hearth-search-wrap.is-expressive) .hearth-clock-stack-side > span {
	padding: 2px 10px;
	border-radius: 999px;
	background: var(--x-surface-high);
	color: var(--x-on-container);
	font-weight: 700;
}

/* Flip: soft tonal tiles, the hinge a gap in the card's own colour. */
:is(.hearth-card.is-expressive, .hearth-x-modal, .hearth-search-wrap.is-expressive) .hearth-clock-flip {
	gap: 8px;
}

:is(.hearth-card.is-expressive, .hearth-x-modal, .hearth-search-wrap.is-expressive) .hearth-clock-flip-tile {
