}

:is(.hearth-card.is-expressive, .hearth-x-modal, .hearth-search-wrap.is-expressive) .hearth-clock-flip-tile.is-minutes {
	background: var(--x-tertiary-container);
}

:is(.hearth-card.is-expressive, .hearth-x-modal, .hearth-search-wrap.is-expressive) .hearth-clock-flip-tile.is-seconds {
	border-radius: 999px;
	background: var(--x-surface-high);
}

:is(.hearth-card.is-expressive, .hearth-x-modal, .hearth-search-wrap.is-expressive) .hearth-clock-flip-tile::after {
	height: 3px;
	margin-top: -1px;
	background: var(--background-primary);
	opacity: 1;
}

:is(.hearth-card.is-expressive, .hearth-x-modal, .hearth-search-wrap.is-expressive) .hearth-clock-flip-num {
	font-weight: 800;
	letter-spacing: -0.05em;
	color: var(--x-on-container);
}

:is(.hearth-card.is-expressive, .hearth-x-modal, .hearth-search-wrap.is-expressive) .hearth-clock-flip-tile.is-minutes .hearth-clock-flip-num {
	color: var(--x-on-tertiary-container);
}

:is(.hearth-card.is-expressive, .hearth-x-modal, .hearth-search-wrap.is-expressive) .hearth-clock-flip-tile.is-turning .hearth-clock-flip-num {
	animation: hearth-clock-flip-x 480ms cubic-bezier(0.34, 1.56, 0.64, 1);
}

/* A springier turn that overshoots, the way Expressive motion settles. */
@keyframes hearth-clock-flip-x {
	from {
		transform: rotateX(-90deg) scale(0.9);
		opacity: 0;
	}
	to {
		transform: none;
		opacity: 1;
	}
}

:is(.hearth-card.is-expressive, .hearth-x-modal, .hearth-search-wrap.is-expressive) .hearth-clock-flip-p {
	padding: 2px 10px;
	border-radius: 999px;
	background: var(--x-surface-high);
	color: var(--x-on-container);
	font-weight: 700;
}

/* Rings: thick strokes, each ring's progress Material's wavy indicator. */
:is(.hearth-card.is-expressive, .hearth-x-modal, .hearth-search-wrap.is-expressive) .hearth-clock-ring-track {
	stroke: var(--x-surface-high);
	stroke-width: 5;
}

:is(.hearth-card.is-expressive, .hearth-x-modal, .hearth-search-wrap.is-expressive) .hearth-clock-ring-bar {
	stroke: var(--x-primary);
	stroke-width: 4;
}

:is(.hearth-card.is-expressive, .hearth-x-modal, .hearth-search-wrap.is-expressive) .hearth-clock-ring-bar.is-hours {
	stroke: var(--x-tertiary);
}

:is(.hearth-card.is-expressive, .hearth-x-modal, .hearth-search-wrap.is-expressive) .hearth-clock-ring-bar.is-seconds {
	stroke: var(--x-on-container);
	stroke-width: 3;
}

:is(.hearth-card.is-expressive, .hearth-x-modal, .hearth-search-wrap.is-expressive) .hearth-clock-ring-track.is-seconds {
	stroke-width: 4;
}

:is(.hearth-card.is-expressive, .hearth-x-modal, .hearth-search-wrap.is-expressive) .hearth-clock-ring-time {
	fill: var(--x-on-container);
	font-weight: 800;
	letter-spacing: -0.05em;
}

/* Shapes (Expressive only): each digit on a shape of its own. */
:is(.hearth-card.is-expressive, .hearth-x-modal, .hearth-search-wrap.is-expressive) .hearth-clock-shapes {
	display: grid;
	grid-template-columns: repeat(4, auto);
	align-items: center;
	justify-content: center;
	gap: 6px;
	--shape: clamp(34px, min(22cqw, var(--clock-room)), 120px);
}

/* A card nearer square than wide stacks the hours over the minutes. */
@container (max-aspect-ratio: 5 / 3) {
	:is(.hearth-card.is-expressive, .hearth-x-modal, .hearth-search-wrap.is-expressive) .hearth-clock-shapes {
		grid-template-columns: repeat(2, auto);
		--shape: clamp(30px, min(40cqw, calc((var(--clock-room) - 6px) / 2)), 120px);
	}
}

:is(.hearth-card.is-expressive, .hearth-x-modal, .hearth-search-wrap.is-expressive) .hearth-clock-shape {
	position: relative;
	display: flex;
	align-items: center;
	justify-content: center;
	width: var(--shape);
	height: var(--shape);
}

:is(.hearth-card.is-expressive, .hearth-x-modal, .hearth-search-wrap.is-expressive) .hearth-clock-shape-bg {
	position: absolute;
	inset: 0;
	width: 100%;
	height: 100%;
	fill: var(--x-container);
	transition: transform 400ms cubic-bezier(0.34, 1.56, 0.64, 1);
}

:is(.hearth-card.is-expressive, .hearth-x-modal, .hearth-search-wrap.is-expressive) .hearth-clock-shape:nth-child(odd) .hearth-clock-shape-bg {
	transform: rotate(-12deg);
}

:is(.hearth-card.is-expressive, .hearth-x-modal, .hearth-search-wrap.is-expressive) .hearth-clock-shape.is-hours:first-child .hearth-clock-shape-bg {
	fill: var(--x-primary);
}

:is(.hearth-card.is-expressive, .hearth-x-modal, .hearth-search-wrap.is-expressive) .hearth-clock-shape.is-minutes .hearth-clock-shape-bg {
	fill: var(--x-tertiary-container);
}

:is(.hearth-card.is-expressive, .hearth-x-modal, .hearth-search-wrap.is-expressive) .hearth-clock-shape:nth-child(4) .hearth-clock-shape-bg {
	fill: var(--x-tertiary);
}

:is(.hearth-card.is-expressive, .hearth-x-modal, .hearth-search-wrap.is-expressive) .hearth-clock-shape-num {
	position: relative;
	font-size: calc(var(--shape) * 0.56);
	font-weight: 800;
