}

:is(.hearth-card.is-expressive, .hearth-x-modal, .hearth-search-wrap.is-expressive) .hearth-clock-shape.is-minutes .hearth-clock-shape-num {
	color: var(--x-on-tertiary-container);
}

:is(.hearth-card.is-expressive, .hearth-x-modal, .hearth-search-wrap.is-expressive) .hearth-clock-shape:nth-child(4) .hearth-clock-shape-num {
	color: var(--background-primary);
}

:is(.hearth-card.is-expressive, .hearth-x-modal, .hearth-search-wrap.is-expressive) .hearth-clock-shapes-extra {
