	border-radius: 999px;
	background: var(--x-surface-high);
	color: var(--x-on-container);
	font-size: 0.78rem;
	font-weight: 700;
	font-variant-numeric: tabular-nums;
}

/* Orbit (Expressive only): the hour on a scalloped face, the minute a dot
 * circling its edge. */
:is(.hearth-card.is-expressive, .hearth-x-modal, .hearth-search-wrap.is-expressive) .hearth-clock-orbit {
	width: clamp(64px, min(90cqw, var(--clock-room)), 260px);
	aspect-ratio: 1;
	flex: 0 0 auto;
}

:is(.hearth-card.is-expressive, .hearth-x-modal, .hearth-search-wrap.is-expressive) .hearth-clock-orbit-face {
	fill: var(--x-container);
}

:is(.hearth-card.is-expressive, .hearth-x-modal, .hearth-search-wrap.is-expressive) .hearth-clock-orbit-track {
	fill: none;
	stroke: var(--x-surface-high);
	stroke-width: 1.2;
	stroke-dasharray: 0 1;
	stroke-linecap: round;
}

:is(.hearth-card.is-expressive, .hearth-x-modal, .hearth-search-wrap.is-expressive) .hearth-clock-orbit-min {
	fill: var(--x-primary);
}

:is(.hearth-card.is-expressive, .hearth-x-modal, .hearth-search-wrap.is-expressive) .hearth-clock-orbit-sec {
	fill: var(--x-tertiary);
}

:is(.hearth-card.is-expressive, .hearth-x-modal, .hearth-search-wrap.is-expressive) .hearth-clock-orbit-h {
	fill: var(--x-on-container);
	font-size: 34px;
	font-weight: 800;
	letter-spacing: -0.06em;
	font-variant-numeric: tabular-nums;
}

:is(.hearth-card.is-expressive, .hearth-x-modal, .hearth-search-wrap.is-expressive) .hearth-clock-orbit-m {
	fill: var(--x-on-tertiary-container);
	font-size: 12px;
	font-weight: 800;
	font-variant-numeric: tabular-nums;
}

:is(.hearth-card.is-expressive, .hearth-x-modal, .hearth-search-wrap.is-expressive) .hearth-clock-orbit-p {
	fill: var(--x-on-container);
	font-size: 7px;
	font-weight: 700;
	opacity: 0.8;
}

/* ---- Mini calendar -------------------------------------------------- */
:is(.hearth-card.is-expressive, .hearth-x-modal, .hearth-search-wrap.is-expressive) .hearth-calendar-label {
	font-size: 1rem;
	font-weight: 750;
	letter-spacing: -0.01em;
}

:is(.hearth-card.is-expressive, .hearth-x-modal, .hearth-search-wrap.is-expressive) .hearth-calendar-nav {
	border-radius: 999px;
	background: var(--x-surface-high);
	color: var(--x-on-container);
	box-shadow: none;
}

