.hearth-design-choice.is-expressive .hearth-design-preview-line {
	height: 6px;
	background: color-mix(in srgb, var(--hd-accent) 55%, var(--text-normal));
}

.hearth-design-choice.is-expressive .hearth-design-preview-row {
	border-radius: 999px;
	background: var(--hd-tone);
}

.hearth-design-choice.is-expressive .hearth-design-preview-button {
	border-radius: 999px;
	background: var(--hd-accent);
}

/* =============================================================================
 * Terminal mode (src/tui/)
 * =============================================================================
 *
 * The whole plugin as a text interface. Everything below is scoped to one of
 * four roots, so nothing here reaches anything that isn't Hearth's:
 *
 *   .hearth-tui          a Hearth view drawn in terminal mode
 *   .hearth-t-modal      a Hearth dialog opened while terminal mode is on
 *   .hearth-t-menu       a Hearth menu, likewise
 *   .hearth-t-settings   Hearth's settings pane, likewise
 *
 * The board is a character grid. Every position on it is a whole number of
 * cells — `--tui-ch` wide and `--tui-lh` tall, measured from the font by
 * src/tui/metrics.ts — so the text inside a card body and the box-drawn frame
 * around it can never drift apart.
 *
 * The font is JetBrains Mono, subset to Latin (with Czech and the rest of
 * Latin Extended), Greek, Cyrillic, box drawing, block elements and the symbol
 * blocks terminal mode draws with, and embedded here so every glyph on the
 * grid comes from the one font and sits at exactly one cell.
 *   Copyright 2020 The JetBrains Mono Project Authors
 *   (https://github.com/JetBrains/JetBrainsMono), licensed under the SIL Open
 *   Font License 1.1. The notice and the licence travel inside the font's own
 *   name records (0, 13 and 14); the full text is also in the repository at
 *   assets/fonts/JetBrainsMono-OFL.txt. JetBrains Mono declares no Reserved
 *   Font Name; the subset is served here as "Hearth Mono" all the same.
 * Bold is synthesised from the regular face, which keeps the advance width and
 * halves what the stylesheet carries.
 */
@font-face {
	font-family: "Hearth Mono";
	font-style: normal;
	font-weight: 400;
	font-display: swap;
	src: url("data:font/woff2;base64,") format("woff2");
}

/* ---- Colour schemes ---------------------------------------------------------
 * "theme" (the default) reads every colour from the Obsidian theme. The fixed
 * schemes set both the terminal's own colours and the theme variables a
 * graphical card body or a dialog control reads, so those match too. */
.hearth-tui,
.hearth-t-modal,
.hearth-t-menu,
.hearth-t-settings {
	--tui-font: "Hearth Mono", "SF Mono", Menlo, Consolas, "DejaVu Sans Mono", monospace;
	--tui-bg: var(--background-primary);
	--tui-bg-alt: var(--background-secondary);
	--tui-fg: var(--text-normal);
	--tui-dim: var(--text-muted);
	--tui-faint: var(--text-faint);
	--tui-line: var(--text-faint);
	--tui-accent: var(--text-accent);
	--tui-sel-bg: var(--text-accent);
	--tui-sel-fg: var(--background-primary);
	--tui-hdr-bg: var(--color-green);
	--tui-hdr-fg: var(--background-primary);
	--tui-green: var(--color-green);
	--tui-red: var(--color-red);
	--tui-yellow: var(--color-yellow);
	--tui-blue: var(--color-blue);
	--tui-magenta: var(--color-purple);
	--tui-cyan: var(--color-cyan);
	--tui-hover: var(--background-modifier-hover);
	--tui-heat1: color-mix(in srgb, var(--tui-green) 28%, var(--tui-bg));
	--tui-heat2: color-mix(in srgb, var(--tui-green) 52%, var(--tui-bg));
	--tui-heat3: color-mix(in srgb, var(--tui-green) 76%, var(--tui-bg));
	--tui-heat4: var(--tui-green);
}

.hearth-tui-scheme-htop {
	--tui-bg: #0e1013;
	--tui-bg-alt: #151920;
	--tui-fg: #d4d7dc;
	--tui-dim: #7c8390;
	--tui-faint: #555c67;
	--tui-line: #3b414b;
	--tui-accent: #5fd0e0;
	--tui-sel-bg: #5fd0e0;
	--tui-sel-fg: #0e1013;
	--tui-hdr-bg: #6fbf73;
	--tui-hdr-fg: #0e1013;
	--tui-green: #8ccf7e;
	--tui-red: #ef7474;
	--tui-yellow: #e5c07b;
	--tui-blue: #6aa7f0;
	--tui-magenta: #c792ea;
	--tui-cyan: #5fd0e0;
	--tui-hover: #1d2229;
}

.hearth-tui-scheme-hearth {
	--tui-bg: #16141b;
	--tui-bg-alt: #1d1a24;
	--tui-fg: #e6e1ef;
	--tui-dim: #8c84a0;
	--tui-faint: #5f5870;
	--tui-line: #4a4459;
	--tui-accent: #b8a4f0;
	--tui-sel-bg: #b8a4f0;
	--tui-sel-fg: #16141b;
	--tui-hdr-bg: #8e7cc3;
	--tui-hdr-fg: #16141b;
	--tui-green: #9fd4a3;
	--tui-red: #f08a8a;
	--tui-yellow: #ecc98a;
	--tui-blue: #93b4f5;
	--tui-magenta: #d9a4f0;
	--tui-cyan: #9ed8e6;
	--tui-hover: #221f2a;
	--tui-heat1: #3a2f55;
	--tui-heat2: #5b4a8a;
	--tui-heat3: #8e7cc3;
	--tui-heat4: #c9b8ff;
}

.hearth-tui-scheme-amber {
	--tui-bg: #100b03;
	--tui-bg-alt: #1a1206;
	--tui-fg: #ffb341;
	--tui-dim: #a8742a;
	--tui-faint: #7a5418;
	--tui-line: #5c4216;
	--tui-accent: #ffd28a;
	--tui-sel-bg: #ffb341;
	--tui-sel-fg: #100b03;
	--tui-hdr-bg: #ffb341;
	--tui-hdr-fg: #100b03;
	--tui-green: #ffcf7a;
	--tui-red: #ff7a3d;
	--tui-yellow: #ffe0a3;
	--tui-blue: #e0a050;
	--tui-magenta: #ffc070;
	--tui-cyan: #ffd28a;
	--tui-hover: #23180a;
	--tui-heat1: #4a3210;
	--tui-heat2: #7a5418;
	--tui-heat3: #b87d22;
	--tui-heat4: #ffb341;
}

.hearth-tui-scheme-paper {
	--tui-bg: #f3f4f6;
	--tui-bg-alt: #e8eaee;
	--tui-fg: #1d2127;
	--tui-dim: #5f6773;
	--tui-faint: #8a929e;
	--tui-line: #aeb5bf;
	--tui-accent: #006d85;
	--tui-sel-bg: #006d85;
	--tui-sel-fg: #ffffff;
	--tui-hdr-bg: #2e7d32;
	--tui-hdr-fg: #ffffff;
	--tui-green: #2e7d32;
	--tui-red: #b42318;
	--tui-yellow: #8a5a00;
	--tui-blue: #1f5fbf;
	--tui-magenta: #8a3aa0;
	--tui-cyan: #006d85;
	--tui-hover: #e3e6ea;
	--tui-heat1: #c6e7cf;
	--tui-heat2: #8fcf9f;
	--tui-heat3: #4fa566;
	--tui-heat4: #1f6f3a;
}

/* A fixed scheme also repaints the theme variables everything else reads. */
:is(.hearth-tui-scheme-htop, .hearth-tui-scheme-hearth, .hearth-tui-scheme-amber, .hearth-tui-scheme-paper) {
	--background-primary: var(--tui-bg);
	--background-primary-alt: var(--tui-bg-alt);
	--background-secondary: var(--tui-bg-alt);
	--background-secondary-alt: var(--tui-bg-alt);
	--background-modifier-hover: var(--tui-hover);
	--background-modifier-border: var(--tui-line);
	--background-modifier-border-hover: var(--tui-dim);
	--background-modifier-form-field: var(--tui-bg);
	--text-normal: var(--tui-fg);
	--text-muted: var(--tui-dim);
	--text-faint: var(--tui-faint);
	--text-accent: var(--tui-accent);
	--text-accent-hover: var(--tui-accent);
	--interactive-accent: var(--tui-accent);
	--interactive-accent-hover: var(--tui-accent);
	--text-on-accent: var(--tui-sel-fg);
	--color-green: var(--tui-green);
	--color-red: var(--tui-red);
	--color-yellow: var(--tui-yellow);
	--color-blue: var(--tui-blue);
	--color-purple: var(--tui-magenta);
	--color-cyan: var(--tui-cyan);
	--color-orange: var(--tui-yellow);
	--icon-color: var(--tui-dim);
}

/* ---- The view ----------------------------------------------------------------- */
.hearth-view.hearth-tui {
	background: var(--tui-bg);
	color: var(--tui-fg);
	font-family: var(--tui-font);
	font-size: var(--tui-font-size, 13px);
	line-height: 1.32;
	font-variant-ligatures: none;
	font-variant-numeric: tabular-nums;
	font-feature-settings: "calt" 0, "liga" 0;
}

.hearth-tui .hearth-tui-scroll {
	--hearth-scroll-pad-x: 12px;
	--hearth-scroll-pad-top: 8px;
	display: flex;
	flex-direction: column;
	padding: 8px 12px 0;
	/* The board keeps its column count down to a readable width; narrower
	 * than that, the pane scrolls sideways instead of squeezing the cards. */
	overflow-x: auto;
}

.hearth-tui .hearth-tui-screen {
	flex: 1 0 auto;
	display: flex;
	flex-direction: column;
	min-width: 0;
}

.hearth-tui-line {
	white-space: pre;
	overflow: hidden;
}

.hearth-tui-probe,
.hearth-tui-probe-inline {
	position: absolute;
	visibility: hidden;
	white-space: pre;
	pointer-events: none;
	left: -10000px;
	top: 0;
}

.hearth-tui-probe {
	width: max-content;
}

/* ---- Text styles ---------------------------------------------------------------- */
:is(.hearth-tui, .hearth-t-modal) .hearth-tui-dim { color: var(--tui-dim); }
:is(.hearth-tui, .hearth-t-modal) .hearth-tui-faint { color: var(--tui-faint); }
:is(.hearth-tui, .hearth-t-modal) .hearth-tui-accent { color: var(--tui-accent); }
:is(.hearth-tui, .hearth-t-modal) .hearth-tui-green { color: var(--tui-green); }
:is(.hearth-tui, .hearth-t-modal) .hearth-tui-red { color: var(--tui-red); }
:is(.hearth-tui, .hearth-t-modal) .hearth-tui-yellow { color: var(--tui-yellow); }
:is(.hearth-tui, .hearth-t-modal) .hearth-tui-blue { color: var(--tui-blue); }
:is(.hearth-tui, .hearth-t-modal) .hearth-tui-magenta { color: var(--tui-magenta); }
:is(.hearth-tui, .hearth-t-modal) .hearth-tui-cyan { color: var(--tui-cyan); }
:is(.hearth-tui, .hearth-t-modal) .hearth-tui-heat1 { color: var(--tui-heat1); }
:is(.hearth-tui, .hearth-t-modal) .hearth-tui-heat2 { color: var(--tui-heat2); }
:is(.hearth-tui, .hearth-t-modal) .hearth-tui-heat3 { color: var(--tui-heat3); }
:is(.hearth-tui, .hearth-t-modal) .hearth-tui-heat4 { color: var(--tui-heat4); }
:is(.hearth-tui, .hearth-t-modal) .hearth-tui-bold { font-weight: 700; }
:is(.hearth-tui, .hearth-t-modal) .hearth-tui-italic { font-style: italic; }
:is(.hearth-tui, .hearth-t-modal) .hearth-tui-underline { text-decoration: underline; text-underline-offset: 2px; }
:is(.hearth-tui, .hearth-t-modal) .hearth-tui-strike { text-decoration: line-through; }
:is(.hearth-tui, .hearth-t-modal) .hearth-tui-header { background: var(--tui-hdr-bg); color: var(--tui-hdr-fg); }
:is(.hearth-tui, .hearth-t-modal) .hearth-tui-header-sort { background: var(--tui-sel-bg); color: var(--tui-sel-fg); font-weight: 700; }
/* A solid cell, painted as background so neighbouring rows touch with no gap
 * between them — a block glyph stops short of the line height. */
:is(.hearth-tui, .hearth-t-modal) .hearth-tui-block { background: var(--tui-accent); }
/* A full cell of a chart: its colour as a background, so stacked cells meet
 * without the gap a block glyph leaves inside a taller line. */
:is(.hearth-tui, .hearth-t-modal) .hearth-tui-solid { background: currentColor; }
/* An inline background covers only the font's content box, which is shorter
 * than the line; a solid cell is stretched to the whole line so the rows of a
 * chart or of big digits meet. */
:is(.hearth-tui, .hearth-t-modal) .hearth-tui-bg { background: var(--tui-seg-bg); }
:is(.hearth-tui, .hearth-t-modal) :is(.hearth-tui-solid, .hearth-tui-block, .hearth-tui-bg) {
	display: inline-block;
	height: 1lh;
	vertical-align: top;
}
:is(.hearth-tui, .hearth-t-modal) .hearth-tui-reverse,
:is(.hearth-tui, .hearth-t-modal) .hearth-tui-reverse:hover {
	background: var(--tui-sel-bg);
	color: var(--tui-sel-fg);
}
:is(.hearth-tui, .hearth-t-modal) .hearth-tui-rule { color: var(--tui-line); }

.hearth-tui-wide {
	display: inline-block;
	width: 2ch;
	text-align: center;
	overflow: hidden;
	vertical-align: top;
}

.hearth-tui-act {
	cursor: pointer;
	border-radius: 0;
}

.hearth-tui-act:hover {
	background: var(--tui-hover);
}

.hearth-tui-act:focus-visible {
	outline: 1px solid var(--tui-accent);
	outline-offset: -1px;
}

/* ---- The board ---------------------------------------------------------------- */
.hearth-tui .hearth-tui-dash {
	position: relative;
	flex: 1 0 auto;
	min-width: 0;
	padding: 4px 0 8px;
}

.hearth-tui-board {
	position: relative;
	width: calc(var(--tui-cols, 80) * var(--tui-ch, 8px));
	height: calc(var(--tui-rows, 24) * var(--tui-lh, 17px));
	outline: none;
	user-select: none;
}

.hearth-tui-board.is-dragging {
	cursor: grabbing;
}

.hearth-tui-frames {
	position: absolute;
	inset: 0;
	color: var(--tui-line);
}

.hearth-tui-frames .hearth-tui-line {
	height: var(--tui-lh, 17px);
}

.hearth-tui-body {
	position: absolute;
	z-index: 1;
	left: calc(var(--tui-x) * var(--tui-ch));
	top: calc(var(--tui-y) * var(--tui-lh));
	width: calc(var(--tui-w) * var(--tui-ch));
	height: calc(var(--tui-h) * var(--tui-lh));
	overflow-x: hidden;
	overflow-y: auto;
	scrollbar-width: none;
	user-select: text;
}

.hearth-tui-body::-webkit-scrollbar {
	display: none;
}

.hearth-tui-body.is-shielded {
	pointer-events: none;
}

.hearth-tui-textbody {
	position: absolute;
}

.hearth-tui-lines {
	position: relative;
}

/* The lines that stay put while the body scrolls: a toolbar, a table header. */
.hearth-tui-sticky {
	position: sticky;
	top: 0;
	z-index: 1;
	background: var(--tui-bg);
}

.hearth-tui-mounts {
	position: absolute;
	inset: 0 auto auto 0;
	width: 100%;
	height: 0;
}

.hearth-tui-mount {
	position: absolute;
	left: calc(var(--tui-x) * var(--tui-ch, 1ch));
	top: calc(var(--tui-y) * var(--tui-lh, 1.32em));
	width: calc(var(--tui-w) * var(--tui-ch, 1ch));
	height: calc(var(--tui-h) * var(--tui-lh, 1.32em));
}

/* Controls a text renderer mounts: a field, an editor. They are text too. */
.hearth-tui-mount :is(textarea, input) {
	width: 100%;
	height: 100%;
	margin: 0;
	padding: 0;
	border: 0;
	border-radius: 0;
	box-shadow: none;
	background: transparent;
	color: var(--tui-fg);
	font: inherit;
	line-height: inherit;
	resize: none;
	caret-color: var(--tui-accent);
}

.hearth-tui-mount :is(textarea, input):focus {
	background: var(--tui-hover);
	box-shadow: none;
}

.hearth-tui-mount :is(textarea, input)::placeholder {
	color: var(--tui-faint);
}

/* ---- A card drawn graphically, inside its frame ------------------------------- */
.hearth-tui-body.is-graphical {
	overflow: hidden;
}

.hearth-tui .hearth-tui-guicard,
.hearth-t-modal .hearth-tui-guicard {
	position: absolute;
	inset: 0;
	display: flex;
	flex-direction: column;
	margin: 0;
	padding: 0;
	border: 0;
	border-radius: 0;
	box-shadow: none;
	background: transparent;
	backdrop-filter: none;
	--card-opacity: 0;
	--hearth-card-radius: 0px;
	--card-border-width: 0px;
}

.hearth-tui .hearth-tui-guicard > .hearth-card-body,
.hearth-t-modal .hearth-tui-guicard > .hearth-card-body {
	flex: 1;
	min-height: 0;
	padding: 0;
	overflow: auto;
	font-family: var(--tui-font);
}

.hearth-tui .hearth-tui-guicard :is(img, video, canvas) {
	image-rendering: auto;
	border-radius: 0;
}

/* ---- Tabs, title, toolbar ------------------------------------------------------ */
.hearth-tui-tabs,
.hearth-tui-titlerow,
.hearth-tui-toolbar {
	flex: none;
	min-width: 0;
}

.hearth-tui-titlerow {
	margin-bottom: 4px;
}

.hearth-tui-toolbar {
	margin-top: 4px;
}

/* ---- Search: Hearth's search section, in terminal dress ------------------------ */
.hearth-tui .hearth-tui-searchwrap {
	display: block;
	margin: 0 0 4px;
	max-width: none;
}

.hearth-tui .hearth-tui-searchwrap .hearth-search-col {
	position: relative;
	width: 100%;
}

.hearth-tui .hearth-tui-searchrow {
	display: flex;
	align-items: center;
	gap: 1ch;
	min-width: 0;
}

.hearth-tui .hearth-tui-searchlabel {
	flex: none;
	padding: 0 1ch;
	background: var(--tui-sel-bg);
	color: var(--tui-sel-fg);
	font-weight: 700;
}

.hearth-tui .hearth-tui-searchwrap .hearth-search-bar {
	flex: 1;
	min-width: 0;
	height: auto;
	padding: 0;
	border: 0;
	border-bottom: 1px dashed var(--tui-line);
	border-radius: 0;
	box-shadow: none;
	background: transparent;
	backdrop-filter: none;
}

.hearth-tui .hearth-tui-searchwrap .hearth-search-bar:focus-within {
	border-bottom-color: var(--tui-accent);
}

.hearth-tui .hearth-tui-searchwrap .hearth-search-icon {
	display: none;
}

.hearth-tui .hearth-tui-searchwrap .hearth-search-input {
	height: var(--tui-lh, 1.32em);
	padding: 0 1ch;
	border: 0;
	border-radius: 0;
	box-shadow: none;
	background: transparent;
	color: var(--tui-fg);
	font: inherit;
	caret-color: var(--tui-accent);
}

.hearth-tui .hearth-tui-searchwrap .hearth-search-input::placeholder {
	color: var(--tui-faint);
}

.hearth-tui .hearth-tui-searchwrap .hearth-newnote {
	height: auto;
	padding: 0;
	border: 0;
	border-radius: 0;
	box-shadow: none;
	background: transparent;
	color: var(--tui-accent);
	font: inherit;
}

.hearth-tui .hearth-tui-searchwrap .hearth-newnote::before { content: "["; }
.hearth-tui .hearth-tui-searchwrap .hearth-newnote::after { content: "]"; }

.hearth-tui .hearth-tui-searchwrap .hearth-newnote:hover {
	background: var(--tui-hover);
}

.hearth-tui .hearth-tui-searchwrap .hearth-newnote-icon {
	display: none;
}

.hearth-tui .hearth-tui-searchwrap .hearth-searchonline {
	display: inline-flex;
	gap: 0;
}

.hearth-tui .hearth-tui-searchwrap .hearth-filters {
	display: flex;
	flex-wrap: wrap;
	gap: 0 1ch;
	margin: 0;
	padding: 0;
}

.hearth-tui .hearth-tui-searchwrap .hearth-filter {
	height: auto;
	padding: 0 1ch;
	border: 0;
	border-radius: 0;
	box-shadow: none;
	background: transparent;
	color: var(--tui-dim);
	font: inherit;
}

.hearth-tui .hearth-tui-searchwrap .hearth-filter.is-active {
	background: var(--tui-sel-bg);
	color: var(--tui-sel-fg);
}

.hearth-tui .hearth-tui-searchwrap .hearth-filter-icon {
	display: none;
}

.hearth-tui .hearth-tui-searchwrap .hearth-search-results {
	top: calc(100% + 2px);
	padding: 0;
	border: 1px solid var(--tui-accent);
	border-radius: 0;
	box-shadow: none;
	background: var(--tui-bg);
	background-image: none;
	backdrop-filter: none;
	font-family: var(--tui-font);
}

/* The search bar card: its results are rows of the card, not a dropdown
 * over the board. */
.hearth-tui .hearth-tui-cardsearch,
.hearth-tui .hearth-tui-cardsearch .hearth-search-col {
	height: 100%;
	display: flex;
	flex-direction: column;
	margin: 0;
	padding: 0;
}

.hearth-tui .hearth-tui-cardsearch .hearth-search-results {
	position: static;
	flex: 1 1 auto;
	min-height: 0;
	max-height: none;
	overflow-y: auto;
	border: 0;
	border-top: 1px dashed var(--tui-faint);
	margin-top: 0;
}

.hearth-tui .hearth-tui-searchwrap .hearth-result {
	gap: 1ch;
	padding: 0 1ch;
	border-radius: 0;
}

.hearth-tui .hearth-tui-searchwrap .hearth-result.is-selected,
.hearth-tui .hearth-tui-searchwrap .hearth-result:hover {
	background: var(--tui-sel-bg);
	color: var(--tui-sel-fg);
}

.hearth-tui .hearth-tui-searchwrap .hearth-result.is-selected :is(.hearth-result-path, .hearth-result-badge, .hearth-result-text),
.hearth-tui .hearth-tui-searchwrap .hearth-result:hover :is(.hearth-result-path, .hearth-result-badge, .hearth-result-text) {
	color: inherit;
}

/* Every part of a result on the grid's own size: a name, a path, an excerpt
 * are all one line of the terminal's text. */
.hearth-tui .hearth-tui-searchwrap .hearth-result :is(.hearth-result-name, .hearth-result-path, .hearth-result-text, .hearth-result-badge) {
	font-size: inherit;
	line-height: inherit;
	font-weight: normal;
}

.hearth-tui .hearth-tui-searchwrap .hearth-result .hearth-result-name {
	font-weight: bold;
}

.hearth-tui .hearth-tui-searchwrap .hearth-result-icon {
	flex: none;
	width: 2ch;
	color: var(--tui-dim);
}

.hearth-tui .hearth-tui-searchwrap .hearth-result-badge {
	border-radius: 0;
	background: transparent;
	color: var(--tui-magenta);
}

.hearth-tui .hearth-tui-searchwrap :is(.hearth-instant, .hearth-instant *) {
	border-radius: 0;
	box-shadow: none;
}

.hearth-tui .hearth-tui-searchwrap .hearth-instant-value {
	color: var(--tui-accent);
	font-weight: 700;
}

/* ---- Status line and function keys --------------------------------------------- */
.hearth-tui .hearth-tui-bottom {
	position: sticky;
	bottom: 0;
	z-index: 5;
	flex: none;
	padding: 2px 0 calc(6px + env(safe-area-inset-bottom, 0px));
	background: var(--tui-bg);
}

.hearth-tui-fkeys {
	display: flex;
	flex-wrap: wrap;
	white-space: pre;
}

.hearth-tui-fkey {
	display: inline-flex;
	cursor: pointer;
}

.hearth-tui-fkey-n {
	color: var(--tui-fg);
}

.hearth-tui-fkey-label {
	min-width: 7ch;
	margin-right: 1ch;
	padding-right: 1ch;
	background: var(--tui-sel-bg);
	color: var(--tui-sel-fg);
}

.hearth-tui-fkey:hover .hearth-tui-fkey-label {
	background: var(--tui-accent);
	filter: brightness(1.12);
}

/* ---- Icons drawn as characters (src/glyphs.ts) --------------------------------- */
.hearth-glyph {
	display: inline-flex;
	align-items: center;
	justify-content: center;
	min-width: 1ch;
	font-family: "Hearth Mono", var(--font-monospace);
	font-style: normal;
	font-weight: 400;
	line-height: 1;
	white-space: pre;
}

.hearth-glyph > svg {
	display: none;
}

/* ---- Dialogs ------------------------------------------------------------------- */
.modal.hearth-t-modal {
	border: 3px double var(--tui-line);
	border-radius: 0;
	box-shadow: none;
	background: var(--tui-bg);
	color: var(--tui-fg);
	font-family: var(--tui-font);
	font-variant-ligatures: none;
	backdrop-filter: none;
}

.hearth-t-modal :is(.modal-title, .modal-content, .setting-item, .setting-item-name, .setting-item-description, input, textarea, select, button, .dropdown) {
	font-family: var(--tui-font);
}

.hearth-t-modal .modal-title {
	display: inline-block;
	padding: 0 1ch;
	background: var(--tui-sel-bg);
	color: var(--tui-sel-fg);
	font-size: inherit;
	font-weight: 700;
}

.hearth-t-modal .modal-close-button {
	border-radius: 0;
}

.hearth-t-modal .modal-close-button::before {
	content: "[x]";
	color: var(--tui-dim);
}

.hearth-t-modal :is(button, .mod-cta, .dropdown, input[type="text"], input[type="search"], input[type="number"], input[type="date"], input[type="time"], textarea) {
	border-radius: 0;
	box-shadow: none;
}

.hearth-t-modal button:not(.clickable-icon):not(.modal-close-button) {
	border: 0;
	background: transparent;
	color: var(--tui-accent);
}

.hearth-t-modal button:not(.clickable-icon):not(.modal-close-button)::before { content: "[ "; }
.hearth-t-modal button:not(.clickable-icon):not(.modal-close-button)::after { content: " ]"; }

.hearth-t-modal button:not(.clickable-icon):not(.modal-close-button):hover {
	background: var(--tui-hover);
}

.hearth-t-modal button.mod-cta {
	background: var(--tui-sel-bg);
	color: var(--tui-sel-fg);
}

.hearth-t-modal button.mod-warning {
	color: var(--tui-red);
}

.hearth-t-modal :is(input[type="text"], input[type="search"], input[type="number"], input[type="date"], input[type="time"], textarea) {
	border: 0;
	border-bottom: 1px dashed var(--tui-line);
	background: transparent;
}

.hearth-t-modal :is(input, textarea):focus {
	border-bottom-color: var(--tui-accent);
	box-shadow: none;
}

.hearth-t-modal .dropdown {
	border: 0;
	border-bottom: 1px dashed var(--tui-line);
	background-color: transparent;
}

/* A toggle becomes a checkbox you can read: [x] or [ ]. */
:is(.hearth-t-modal, .hearth-t-settings) .checkbox-container {
	width: 3ch;
	height: auto;
	border-radius: 0;
	background: transparent;
	box-shadow: none;
}

:is(.hearth-t-modal, .hearth-t-settings) .checkbox-container::before {
	content: "[ ]";
	color: var(--tui-dim);
	font-family: var(--tui-font);
}

:is(.hearth-t-modal, .hearth-t-settings) .checkbox-container.is-enabled::before {
	content: "[x]";
	color: var(--tui-accent);
}

:is(.hearth-t-modal, .hearth-t-settings) .checkbox-container::after {
	display: none;
}

.hearth-t-modal .setting-item {
	border-top: 1px dashed var(--tui-line);
}

.hearth-t-modal :is(.hearth-modal-tabs, .hearth-tabs) * {
	border-radius: 0;
}

/* Zoom: a card at full size. */
.modal.hearth-tui-zoom {
	width: min(96vw, 1400px);
	max-width: none;
	height: min(90vh, 1000px);
	max-height: none;
}

.hearth-tui-zoom .modal-content {
	flex: 1;
	display: flex;
	min-height: 0;
}

.hearth-tui-zoombody {
	position: relative;
	flex: 1;
	min-height: 0;
	overflow-x: hidden;
	overflow-y: auto;
	outline: none;
	font-size: var(--tui-font-size, 13px);
	line-height: 1.32;
	scrollbar-width: none;
}

.hearth-tui-zoombody::-webkit-scrollbar {
	display: none;
}

.hearth-tui-zoombody.hearth-tui-textbody {
	position: relative;
}

.hearth-tui-helpbody {
	font-size: var(--tui-font-size, 13px);
	line-height: 1.32;
}

/* ---- Menus --------------------------------------------------------------------- */
.menu.hearth-t-menu {
	padding: 0;
	border: 3px double var(--tui-line);
	border-radius: 0;
	box-shadow: none;
	background: var(--tui-bg);
	color: var(--tui-fg);
	font-family: var(--tui-font);
	backdrop-filter: none;
}

.hearth-t-menu .menu-item {
	padding: 0 2ch 0 1ch;
	border-radius: 0;
}

.hearth-t-menu .menu-item-icon {
	display: none;
}

.hearth-t-menu .menu-item.selected:not(.is-disabled):not(.is-label),
.hearth-t-menu .menu-item:hover:not(.is-disabled):not(.is-label) {
	background: var(--tui-sel-bg);
	color: var(--tui-sel-fg);
}

.hearth-t-menu .menu-item.is-warning {
	color: var(--tui-red);
}

.hearth-t-menu .menu-separator {
	margin: 0;
	border-bottom: 1px solid var(--tui-line);
}

.hearth-t-menu .menu-item.mod-checked::before,
.hearth-t-menu .menu-item-title::before {
	font-family: var(--tui-font);
}

/* ---- The settings pane ----------------------------------------------------------- */
.hearth-t-settings {
	font-family: var(--tui-font);
	font-variant-ligatures: none;
}

.hearth-t-settings :is(input, select, textarea, button, .dropdown, .setting-item-name, .setting-item-description) {
	font-family: var(--tui-font);
}

.hearth-t-settings :is(.hearth-section-body, .hearth-settings-index-rows, .hearth-design-hero, .hearth-design-choice) {
	border-radius: 0;
	box-shadow: none;
}

.hearth-t-settings :is(.hearth-section-body, .hearth-settings-index-rows) {
	border: 1px solid var(--tui-line);
}

/* ---- The Terminal choice in the design hero ------------------------------------ */
.hearth-design-choices.has-three {
	grid-template-columns: repeat(3, minmax(0, 1fr));
}

@media (max-width: 720px) {
	.hearth-design-choices.has-three {
		grid-template-columns: minmax(0, 1fr);
	}
}

.hearth-design-preview.is-terminal {
	display: flex;
	flex-direction: column;
	justify-content: center;
	align-items: center;
	padding: 10px 6px;
	border-radius: 0;
	background: #0e1013;
	color: #d4d7dc;
	font-family: "Hearth Mono", var(--font-monospace);
	font-size: 11px;
	line-height: 1.32;
	overflow: hidden;
}

.hearth-design-preview-tline {
	white-space: pre;
}

.hearth-design-preview-tline:first-child {
	color: #5fd0e0;
}

/* ---- Text renderers' own controls ---------------------------------------------- */
.hearth-tui-calc-prompt {
	display: flex;
	align-items: center;
}

.hearth-tui-mount .hearth-tui-calc-input {
	flex: 1;
	min-width: 0;
	height: var(--tui-lh, 1.32em);
	border-bottom: 1px dashed var(--tui-line);
}

.hearth-tui-mount .hearth-tui-calc-input:focus {
	border-bottom-color: var(--tui-accent);
}

.hearth-tui-mount textarea.hearth-tui-editor {
	display: block;
	white-space: pre-wrap;
	overflow-y: auto;
	scrollbar-width: thin;
}

.hearth-tui .hearth-tui-colored,
.hearth-t-modal .hearth-tui-colored {
	color: var(--tui-seg-color);
}

:is(.hearth-tui, .hearth-t-modal) .hearth-tui-reverse.hearth-tui-colored {
	color: var(--tui-sel-fg);
}

/* ==================== Custom Attachment Location (modules/custom-attachment-location) ==================== */
/* 由 src/styles/main.scss 用 sass 编译并入；模块本地 .scss 为参考副本，改动需同步两边。 */
.obsidian-custom-attachment-location.obsidian-dev-utils.code-highlighter-component textarea.tokenized-string-setting-control {
  height: 6em;
}
.obsidian-custom-attachment-location.obsidian-dev-utils.multiple-text-component textarea {
